#include <windows.h>

void PositionCloseButton(HWND hwndFrame, HWND hwndCloseButton, int captionHeight) {
    RECT rectCloseButton;

    // Get the preferred size of the close button
    GetWindowRect(hwndCloseButton, &rectCloseButton);

    int width = rectCloseButton.right - rectCloseButton.left;
    int height = rectCloseButton.bottom - rectCloseButton.top;

    // Calculate the position of the close button
    int x = (GetSystemMetrics(SM_CXFRAME) - width) / 2;
    int y = (captionHeight - height) / 2;

    // Set the position of the close button
    SetWindowPos(hwndCloseButton, NULL, x, y, width, height, SWP_NOZORDER | SWP_NOACTIVATE);
}
